{
  "status": "designed",
  "request": "Which of these channels contain posts that Tom reacted to? Candidates: #design-sync, #roadmap-planning, #support-triage, #eng-standup.",
  "selection_plan": {
    "root_entity": "CONVERSATION",
    "candidate_scope": "Four existing non-DM channels in one workspace, supplied by name/ID in the prompt: #design-sync, #roadmap-planning, #support-triage, #eng-standup. All are readable by the acting user (workspace member).",
    "route_binding": "CONVERSATION contains MESSAGE; that MESSAGE receives a REACTION; the REACTION's contributing USER is the focal identity, matched by users.real_name containing 'Tom'.",
    "identifying_criteria": [
      "focal: exists a Message in the channel with a Reaction whose contributing User.real_name matches 'Tom' (partial/first-name match)",
      "auxiliary: the matched Reaction and matched Message must belong to the same channel (route binding, not an extra independent criterion)"
    ],
    "criteria_count_note": "Only one true identifying criterion (focal); the message/reaction/channel binding is the route path itself, not a second auxiliary."
  },
  "resolution_plan": {
    "mode": "underspecified",
    "cause": "Two distinct users have real_name values matching the partial name 'Tom' used in the request: Tom Rivera and Tom Delgado. Each is the sole qualifying reactor in a different candidate channel (Tom Rivera reacts in #design-sync; Tom Delgado reacts in #roadmap-planning). The request gives no surname, title, or other disambiguator, and does not delegate a choice, so the two channel selections compete on the focal field itself.",
    "competing_singleton_sets": [
      ["#design-sync"],
      ["#roadmap-planning"]
    ],
    "decidability": "Both users' real_name and both channels' qualifying reactions are fully readable via users.info/conversations.history/reactions.get, so the ambiguity is confirmed rather than merely unexplored."
  },
  "negative_plan": {
    "focal_near_miss": {
      "channel": "#support-triage",
      "construction": "A message in #support-triage is authored by Tom Anderson (real_name also matches 'Tom'), but the only reaction on that message comes from a different user, Sara Kim. This is a relationship near miss: a real 'Tom' is present in the channel, but in the author role, not the reactor role required by the focal condition."
    },
    "clean_negative": {
      "channel": "#eng-standup",
      "construction": "A message in #eng-standup is authored and reacted to only by Sara Kim; no user named Tom appears anywhere in this channel's messages or reactions."
    },
    "accidental_match_check": "Verified Tom Rivera, Tom Delgado, and Tom Anderson are three distinct user_ids with distinct real_name strings, each in exactly one of the four candidate channels' message/reaction data; Sara Kim's real_name does not contain 'Tom'. No channel has more than one qualifying-or-near-miss condition simultaneously."
  },
  "environment_plan": "Single workspace (non-null team_id) containing the four candidate channels plus their ordinary member rosters. Seed: Tom Rivera and Tom Delgado each hold a workspace membership and a real_name distinctly containing 'Tom'; Tom Anderson likewise. Sara Kim is a filler user with an unrelated real_name. Each candidate channel gets 1-2 ordinary messages with plausible text (e.g. design review notes, roadmap draft, a support ticket, a standup summary), authored by varied users, with reactions seeded per the negative/positive plan above using real emoji names. Actor is a workspace member with conversations.history/reactions.get access to all four channels; no archived or DM channels involved.",
  "action_plan": "Single read-only reporting task: identify which of the four named channels satisfy the reacted-by-Tom condition. No mutation is requested since the concept (identifying qualifying channels) has no natural supported write operation; the task is answered via conversations.history + reactions.get across the four candidates and users.info to resolve real_name. Because the intended referent is genuinely underspecified between Tom Rivera and Tom Delgado, the correct outcome is to report the ambiguity rather than pick one channel.",
  "reason": null
}
